test('complete pre-change and current default engines retain identical original expansions and literal refusals',{timeout:60000},async()=>{
 assert.equal(hash(COMPLETE_PRE255_ENGINE_SOURCE),COMPLETE_PRE255_ENGINE_SHA256);const url=new URL('../declarative-macro-engine.mjs',import.meta.url),currentSource=readFileSync(url,'utf8'),old=physical(COMPLETE_PRE255_ENGINE_SOURCE,url,'complete-old-engine.mjs'),current=physical(currentSource,url,'complete-current-engine.mjs');retain('01-complete-old-current-engines-before-import',{old,current});const baselineModule=await import(old.url),actualModule=await import(current.url),baseline=baselineModule.createDeclarativeMacroEngine(),actual=actualModule.createDeclarativeMacroEngine(),values=[];let reads=0;const fake=Object.defineProperty({},'sources',{get(){reads++;throw Error('fake grammar');}});assert.throws(()=>actualModule.createDeclarativeMacroEngine(null,fake),/copied or foreign grammar/);assert.equal(reads,0);
 for(const [source,written]of [['macro_rules! sample{($v:ident)=>{($v)};}','word'],['macro_rules! sample{($v:ty)=>{($v)};}','Option<u8>'],['macro_rules! sample{($v:expr)=>{($v)};}','call()'],['macro_rules! sample{($v:tt)=>{($v)};}','"text"']]){const input=originalMacroTrees(written),options={name:'sample',owner:['fixture']},oldResult=callbackTape(()=>{const definition=baseline.compileDeclarativeMacro(source,options);return {definition,expansion:baseline.expandDeclarativeMacro(definition,input)};}),newResult=callbackTape(()=>{const definition=actual.compileDeclarativeMacro(source,options);return {definition,expansion:actual.expandDeclarativeMacro(definition,input)};});values.push({source,written,input,oldResult,newResult});retain('01-full-output-and-callback-tape-'+values.length,values.at(-1));assert.deepEqual(newResult,oldResult);assert.ok(oldResult.tape.some(row=>row.operation==='Hash.update'));assert.ok(oldResult.tape.some(row=>row.operation==='JSON.stringify'));assert.throws(()=>actual.expandDeclarativeMacro(oldResult.value.definition,input),/sealed/);}
 const source='macro_rules! sample{($v:literal)=>{$v};}';for(const engine of [baseline,actual])assert.throws(()=>engine.compileDeclarativeMacro(source,{name:'sample',owner:['fixture']}),/outside the checked initial profile: literal/);retain('01-full-default-engine-results',{values});
});

